/**
 * What the guided uninstall may delete, written once: the uninstall stack
 * (infra/cfn/coderhelm-selfhost-uninstall.yaml, generated by
 * infra/lib/uninstall-stack.ts), the IAM simulator fixture
 * (infra/scripts/deploy-role-sim.py --uninstall) and the tests all use
 * these functions (docs/self-host/uninstall.md, "What the uninstaller may
 * touch").
 *
 * It follows the install's own shape (infra/lib/access.ts):
 *
 * - The uninstall boundary (`coderhelm--uninstall-<stage>-boundary-<id>`) caps the
 *   uninstall stack's three roles: no IAM users or keys, no Organizations,
 *   CloudTrail or GuardDuty, no IAM writes outside `<prefix>-*`, no role
 *   assumed at all, and none of the uninstaller's own pieces changed by
 *   the uninstaller (only CloudFormation, with the credentials of the
 *   person who launched it, changes or removes them).
 * - The uninstall window (`uninstall-window`, an inline policy): what one
 *   verified uninstall build may delete while it runs, bound to its session
 *   (aws:userid) and an end time. The window function writes it after
 *   checking the build, from the statements below with the install's own
 *   names filled in from what it finds in this region:
 *     __ID__      each Launch Stack id of this install in this region
 *     __LAUNCH__  each Launch Stack of this install in this region, by name
 *     __SETUP__   each install progress bucket id (coderhelm-setup-<id>)
 *     __SIB__     each other install whose name starts with this one's
 *                 plus a hyphen (coderhelm-prod-eu inside coderhelm-prod-*)
 *     __BUCKET__  the stacks' own buckets that are in this region (S3 names
 *                 carry no region: coderhelm-<name>-dashboard-<account>)
 *     __DATA__    the data bucket, when it is in this region
 *   A string with a token becomes one string per value; a statement left
 *   with no resource or no condition value is dropped.
 *
 * Every deletion is limited to the install by one of: an exact name built
 * from the install's name and its Launch Stack ids, the install's tag
 * (`coderhelm:install = <prefix>`) where AWS supports it, the install's own
 * permissions boundary on the role, or a name pattern with an explicit deny
 * for every longer install name found ("OtherInstallsInsideThisName").
 */
import { Statement, PolicyDocument, partitionOf } from "./access";

export const INSTALL_TAG = "coderhelm:install";
/** Every uninstaller piece starts with this: coderhelm--uninstall-<stage>-... (docs/self-host/uninstall.md). */
export const UNINSTALL_NS = "coderhelm--uninstall-";
/** The tag the updater puts on a certificate it requests for a domain (lambda/updater). */
export const UPDATER_CERT_TAG = "coderhelm";
export const UNINSTALL_WINDOW_POLICY_NAME = "uninstall-window";
export const UNINSTALL_WINDOW_MINUTES = 100;
export const TOKENS = { userId: "__USER_ID__", expires: "__EXPIRES__", id: "__ID__", launch: "__LAUNCH__", setup: "__SETUP__", sib: "__SIB__", bucket: "__BUCKET__", data: "__DATA__" } as const;
/** Statements whose Sid starts with this are left out unless the uninstall deletes the data too. */
export const DATA_SID = "Data";

export interface UninstallNames {
  partition: string;
  account: string;
  region: string;
  stage: string;
  /** coderhelm-<stage> */
  prefix: string;
  /** The uninstall stack's own short id. */
  uid: string;
  /** The uninstall's own progress id (may be empty). */
  statusId: string;
  boundaryName: string;
  boundaryArn: string;
  buildRole: string;
  windowRole: string;
  starterRole: string;
  project: string;
  windowFunction: string;
  starterFunction: string;
  buildLogGroup: string;
  windowLogGroup: string;
  starterLogGroup: string;
  paramPath: string;
  stackName: string;
}

export function uninstallNames(p: { partition?: string; account: string; region: string; stage: string; uid: string; statusId?: string }): UninstallNames {
  const partition = p.partition ?? partitionOf(p.region);
  const prefix = `coderhelm-${p.stage}`;
  // Outside every install's names: an install name starts with a letter, so
  // no install's coderhelm-<name>-* (nor its deploy role) reaches coderhelm--*.
  const u = `${UNINSTALL_NS}${p.stage}`;
  const boundaryName = `${u}-boundary-${p.uid}`;
  return {
    partition,
    account: p.account,
    region: p.region,
    stage: p.stage,
    prefix,
    uid: p.uid,
    statusId: p.statusId ?? "",
    boundaryName,
    boundaryArn: `arn:${partition}:iam::${p.account}:policy/${boundaryName}`,
    buildRole: `${u}-build-${p.uid}`,
    windowRole: `${u}-window-${p.uid}`,
    starterRole: `${u}-starter-${p.uid}`,
    project: `${u}-${p.uid}`,
    windowFunction: `${u}-window-${p.uid}`,
    starterFunction: `${u}-starter-${p.uid}`,
    buildLogGroup: `/aws/codebuild/${u}-${p.uid}`,
    windowLogGroup: `/aws/lambda/${u}-window-${p.uid}`,
    starterLogGroup: `/aws/lambda/${u}-starter-${p.uid}`,
    paramPath: `/${u}-${p.uid}/window-policy`,
    stackName: u,
  };
}

const doc = (Statement: Statement[]): PolicyDocument => ({ Version: "2012-10-17", Statement });

function at(n: UninstallNames, svc: string, region = n.region): string {
  return `arn:${n.partition}:${svc}:${region}:${n.account}`;
}

/** The uninstaller's own pieces, which nothing it runs may change. */
function own(n: UninstallNames) {
  const U = n.stackName;
  return {
    roles: `arn:${n.partition}:iam::${n.account}:role/${U}-*`,
    policies: `arn:${n.partition}:iam::${n.account}:policy/${U}-*`,
    functions: `${at(n, "lambda")}:function:${U}-*`,
    projects: `${at(n, "codebuild")}:project/${U}-*`,
    params: `${at(n, "ssm")}:parameter/${U}-*`,
    stacks: `${at(n, "cloudformation")}:stack/${U}-*/*`,
    logs: [`${at(n, "logs")}:log-group:/aws/codebuild/${U}-*`, `${at(n, "logs")}:log-group:/aws/lambda/${U}-*`],
    statusBucket: [`arn:${n.partition}:s3:::coderhelm-setup-${n.statusId}`, `arn:${n.partition}:s3:::coderhelm-setup-${n.statusId}/*`],
  };
}

/** IAM writes (the boundary denies them outside the install's names). */
export const IAM_WRITES = [
  "iam:Add*", "iam:Attach*", "iam:Change*", "iam:Create*", "iam:Deactivate*", "iam:Delete*", "iam:Detach*", "iam:Enable*",
  "iam:PassRole", "iam:Put*", "iam:Remove*", "iam:Reset*", "iam:Resync*", "iam:Set*", "iam:Tag*", "iam:Untag*", "iam:Update*", "iam:Upload*",
];

/** The services an uninstall role may use at all. */
export const UNINSTALL_SERVICES = [
  "acm:*", "cloudformation:*", "codebuild:*", "cognito-idp:*", "dynamodb:*", "iam:*", "kms:*", "lambda:*", "logs:*",
  "s3:*", "secretsmanager:*", "ssm:*", "tag:GetResources", "tag:GetTagValues", "sts:GetCallerIdentity",
];

/** The uninstall boundary: the most any uninstall role can do. */
export function uninstallBoundaryPolicy(n: UninstallNames): PolicyDocument {
  const P = n.prefix;
  const iam = `arn:${n.partition}:iam::${n.account}`;
  const o = own(n);
  return doc([
    { Sid: "UninstallServices", Effect: "Allow", Action: UNINSTALL_SERVICES, Resource: "*" },
    {
      Sid: "NoIamUsersOrKeys",
      Effect: "Deny",
      Action: ["iam:CreateUser", "iam:CreateAccessKey", "iam:UpdateAccessKey", "iam:CreateLoginProfile", "iam:UpdateLoginProfile", "iam:AttachUserPolicy",
        "iam:PutUserPolicy", "iam:AddUserToGroup", "iam:CreateGroup", "iam:PutGroupPolicy", "iam:AttachGroupPolicy", "iam:CreateServiceSpecificCredential",
        "iam:UploadSSHPublicKey", "iam:CreateOpenIDConnectProvider", "iam:CreateSAMLProvider", "iam:UpdateAccountPasswordPolicy", "iam:CreateAccountAlias"],
      Resource: "*",
    },
    { Sid: "NoAccountGuardrailChanges", Effect: "Deny", Action: ["organizations:*", "account:*", "cloudtrail:*", "guardduty:*"], Resource: "*" },
    { Sid: "NoRolesAssumed", Effect: "Deny", Action: ["sts:AssumeRole", "sts:AssumeRoleWithWebIdentity", "sts:AssumeRoleWithSAML", "sts:TagSession", "sts:SetSourceIdentity"], Resource: "*" },
    { Sid: "NoIamWritesOutsideTheInstall", Effect: "Deny", Action: IAM_WRITES, NotResource: [`${iam}:role/${P}-*`, `${iam}:policy/${P}-*`, o.roles] },
    { Sid: "NoNewRolesOrPolicies", Effect: "Deny", Action: ["iam:CreateRole", "iam:CreatePolicy", "iam:CreatePolicyVersion", "iam:SetDefaultPolicyVersion", "iam:AttachRolePolicy", "iam:PutRolePermissionsBoundary", "iam:DeleteRolePermissionsBoundary", "iam:UpdateAssumeRolePolicy"], Resource: "*" },
    // A role is passed only to CloudFormation (the install's deploy role, to delete its stacks).
    { Sid: "PassOnlyToCloudFormation", Effect: "Deny", Action: "iam:PassRole", Resource: "*", Condition: { StringNotEquals: { "iam:PassedToService": "cloudformation.amazonaws.com" } } },
    // The uninstaller's own roles and boundary: only CloudFormation, with the
    // launching person's credentials, changes or removes them. The one write
    // allowed is the window itself on the build role (put by the window
    // function, removed by the build and the starter).
    { Sid: "TheUninstallerStaysRoles", Effect: "Deny", Action: IAM_WRITES, Resource: [`${iam}:role/${n.windowRole}`, `${iam}:role/${n.starterRole}`, o.policies] },
    { Sid: "TheUninstallerStaysBuildRole", Effect: "Deny", NotAction: ["iam:PutRolePolicy", "iam:DeleteRolePolicy", "iam:Get*", "iam:List*"], Resource: o.roles },
    { Sid: "TheUninstallerStaysFunctions", Effect: "Deny", NotAction: ["lambda:InvokeFunction", "lambda:Get*", "lambda:List*"], Resource: o.functions },
    { Sid: "TheUninstallerStaysProject", Effect: "Deny", NotAction: ["codebuild:StartBuild", "codebuild:BatchGet*", "codebuild:List*"], Resource: o.projects },
    { Sid: "TheUninstallerStaysParameters", Effect: "Deny", NotAction: ["ssm:GetParameter", "ssm:GetParameters", "ssm:Describe*"], Resource: o.params },
    { Sid: "TheUninstallerStaysStack", Effect: "Deny", NotAction: ["cloudformation:Describe*", "cloudformation:Get*", "cloudformation:List*"], Resource: o.stacks },
    { Sid: "TheUninstallerStaysLogs", Effect: "Deny", NotAction: ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DeleteLogGroup", "logs:Describe*", "logs:List*"], Resource: o.logs },
  ]);
}

/**
 * The uninstall window's statements, with tokens (see the top of this file).
 * Two denies bind it to the build's session and the end time.
 */
export function uninstallWindowStatements(n: UninstallNames): Statement[] {
  const P = n.prefix;
  const A = n.account;
  const part = n.partition;
  const iam = `arn:${part}:iam::${A}`;
  const T = TOKENS;
  const tagged = { [`aws:ResourceTag/${INSTALL_TAG}`]: P };
  const boundaries = `${iam}:policy/${P}-boundary-${T.id}`;
  const deployRoles = `${iam}:role/${P}-deploy-${T.id}`;
  const launchRoles = ["installer", "starter", "window"].map((r) => `${iam}:role/${P}-${r}-${T.id}`);
  const bucket = (name: string) => [`arn:${part}:s3:::${name}`, `arn:${part}:s3:::${name}/*`];
  // Conditions of one statement (the session and the end time are two denies for the whole window, below).
  const s = (x: Statement, extra: Record<string, Record<string, string | string[]>> = {}): Statement => (Object.keys(extra).length ? { ...x, Condition: extra } : x);
  const BUCKET_EMPTYING = ["s3:ListBucket", "s3:ListBucketVersions", "s3:GetBucketLocation", "s3:GetBucketTagging", "s3:GetBucketVersioning", "s3:DeleteObject", "s3:DeleteObjectVersion", "s3:DeleteBucket"];
  const allows: Statement[] = [
    // Read-only: what the uninstaller lists to find the install's pieces and to check nothing is left.
    s({
      Sid: "Reads",
      Effect: "Allow",
      Action: [
        "cloudformation:Describe*", "cloudformation:List*", "s3:ListAllMyBuckets", "s3:GetBucketLocation", "s3:GetBucketTagging", "dynamodb:Describe*", "dynamodb:List*",
        "kms:Describe*", "kms:List*", "cognito-idp:Describe*", "cognito-idp:List*", "secretsmanager:ListSecrets", "logs:Describe*", "ssm:Describe*", "ssm:GetParametersByPath",
        "iam:Get*", "iam:List*", "acm:Describe*", "acm:List*", "tag:Get*", "sts:GetCallerIdentity",
      ],
      Resource: "*",
    }),
    // The install's CloudFormation stacks (CDK): tagged for the install, deleted through its own deploy role.
    s({ Sid: "InstallStacks", Effect: "Allow", Action: "cloudformation:DeleteStack", Resource: `${at(n, "cloudformation")}:stack/${P}-*/*` },
      { StringEquals: { ...tagged, "cloudformation:RoleArn": deployRoles } }),
    s({ Sid: "PassDeployRole", Effect: "Allow", Action: "iam:PassRole", Resource: deployRoles }, { StringEquals: { "iam:PassedToService": "cloudformation.amazonaws.com" } }),
    // The Launch Stack(s) that installed it, by exact name, deleted with these credentials.
    s({ Sid: "LaunchStacks", Effect: "Allow", Action: "cloudformation:DeleteStack", Resource: `${at(n, "cloudformation")}:stack/${T.launch}/*` }, { Null: { "cloudformation:RoleArn": "true" } }),
    // The pieces named for the install. Each action applies only to its own kind of resource:
    //   the Launch Stack's functions, project, parameters and roles, its deploy role and
    //   boundary (each ends in a Launch Stack id of this install), its assets bucket and the
    //   stacks' own buckets and the install's progress buckets (exact names), and the
    //   install's log groups and parameters (longer install names denied below).
    s({
      Sid: "InstallPieces",
      Effect: "Allow",
      Action: [
        "lambda:DeleteFunction", "codebuild:DeleteProject", "ssm:DeleteParameter", "ssm:DeleteParameters", "ssm:GetParameter*",
        "iam:DeleteRole", "iam:DeletePolicy", "iam:DeletePolicyVersion", "logs:DeleteLogGroup", "secretsmanager:GetSecretValue", ...BUCKET_EMPTYING,
      ],
      Resource: [
        `${at(n, "lambda")}:function:${P}-*-${T.id}`, `${at(n, "codebuild")}:project/${T.launch}-installer`, `${iam}:role/${P}-*-${T.id}`, boundaries,
        ...bucket(`${P}-assets-${T.id}-${A}`), ...bucket(T.bucket), ...bucket(`coderhelm-setup-${T.setup}`),
        `${at(n, "logs")}:log-group:/aws/lambda/${P}-*`, `${at(n, "logs")}:log-group:/aws/codebuild/${P}-*`, `${at(n, "ssm")}:parameter/${P}/*`,
        // Hybrid: the registration, read to release the name and links before anything is deleted.
        `${at(n, "secretsmanager")}:secret:coderhelm/${n.stage}/secrets-*`,
      ],
    }),
    // The Launch Stack's custom resource, invoked only by CloudFormation as it deletes the stack.
    s({ Sid: "LaunchCustomResource", Effect: "Allow", Action: "lambda:InvokeFunction", Resource: `${at(n, "lambda")}:function:${P}-starter-${T.id}` },
      { "ForAnyValue:StringEquals": { "aws:CalledVia": "cloudformation.amazonaws.com" } }),
    // Roles (IAM is global): a role's policies come off, and the role goes, only when it carries
    // one of the boundaries of this install's Launch Stacks in this region, or (above) ends in one of their ids.
    s({ Sid: "InstallRoles", Effect: "Allow", Action: ["iam:DeleteRolePolicy", "iam:DetachRolePolicy", "iam:DeleteRole"], Resource: `${iam}:role/${P}-*` }, { StringEquals: { "iam:PermissionsBoundary": boundaries } }),
    s({ Sid: "ReadRegistrationKey", Effect: "Allow", Action: "kms:Decrypt", Resource: `${at(n, "kms")}:key/*` },
      { StringEquals: { ...tagged, "kms:ViaService": `secretsmanager.${n.region}.amazonaws.com` } }),
    // Delete everything only: the data.
    s({ Sid: `${DATA_SID}Tables`, Effect: "Allow", Action: ["dynamodb:DeleteTable", "dynamodb:UpdateTable"], Resource: [`${at(n, "dynamodb")}:table/${P}`, `${at(n, "dynamodb")}:table/${P}-*`] }, { StringEquals: tagged }),
    s({ Sid: `${DATA_SID}Keys`, Effect: "Allow", Action: ["kms:ScheduleKeyDeletion", "kms:DeleteAlias"], Resource: `${at(n, "kms")}:key/*` }, { StringEquals: tagged }),
    s({ Sid: `${DATA_SID}UserPools`, Effect: "Allow", Action: ["cognito-idp:DeleteUserPool", "cognito-idp:UpdateUserPool", "cognito-idp:DeleteUserPoolDomain"], Resource: `${at(n, "cognito-idp")}:userpool/*` }, { StringEquals: tagged }),
    // The table backups, the data bucket, the key aliases (with the tagged key above) and the secret.
    s({
      Sid: `${DATA_SID}Pieces`,
      Effect: "Allow",
      Action: ["dynamodb:DeleteBackup", "kms:DeleteAlias", "secretsmanager:DeleteSecret", ...BUCKET_EMPTYING],
      Resource: [`${at(n, "dynamodb")}:table/${P}/backup/*`, `${at(n, "dynamodb")}:table/${P}-*/backup/*`, `${at(n, "kms")}:alias/${P}-*`, `${at(n, "secretsmanager")}:secret:coderhelm/${n.stage}/*`, ...bucket(T.data)],
    }),
  ];
  return [...allows, ...uninstallWindowDenies(n, allows)];
}

/** Every action the window allows that changes something (the denies below cover all of them). */
export function windowWrites(allows: Statement[]): string[] {
  const reads = /^(\w|-)+:(List|Describe|Get|BatchGet)/;
  return [...new Set(allows.filter((x) => x.Effect === "Allow").flatMap((x) => (Array.isArray(x.Action) ? x.Action : [x.Action as string])).filter((a) => !reads.test(a) && a !== "sts:GetCallerIdentity"))].sort();
}

function uninstallWindowDenies(n: UninstallNames, allows: Statement[]): Statement[] {
  const P = n.prefix;
  const o = own(n);
  const writes = windowWrites(allows);
  // Every allowed resource named `<prefix>-...` again with each longer install name.
  // Only name patterns can reach another install: exact names (with a Launch Stack id) and slash-ended paths can't.
  const patterns = [...new Set(allows.flatMap((x) => (Array.isArray(x.Resource) ? x.Resource : x.Resource ? [x.Resource] : [])).filter((r) => r.includes(`${P}-*`)))];
  const twins = [...new Set(patterns.map((r) => r.split(`${P}-*`).join(`${TOKENS.sib}-*`)))].sort();
  // The build role's idle rights (its log, its progress file, asking for and closing its window) stay for any session.
  const log = `${at(n, "logs")}:log-group:${n.buildLogGroup}`;
  const idle = [`${log}*`, `arn:${n.partition}:s3:::coderhelm-setup-${n.statusId}/status.json`, `${at(n, "lambda")}:function:${n.windowFunction}`, `arn:${n.partition}:iam::${n.account}:role/${n.buildRole}`];
  return [
    // Everything else in the window is this build's session's, until the end time.
    { Sid: "OnlyThisBuild", Effect: "Deny", Action: "*", NotResource: idle, Condition: { StringNotEquals: { "aws:userid": TOKENS.userId } } },
    { Sid: "OnlyUntilTheEnd", Effect: "Deny", Action: "*", NotResource: idle, Condition: { DateGreaterThan: { "aws:CurrentTime": TOKENS.expires } } },
    { Sid: "OtherInstallsInsideThisName", Effect: "Deny", Action: writes, Resource: twins },
    // The uninstaller's own log groups match the install's log names: the starter removes them, not the build.
    // (Its other pieces don't match any allow above, and its boundary denies changing them.)
    { Sid: "NotTheUninstaller", Effect: "Deny", Action: "logs:DeleteLogGroup", Resource: o.logs },
    { Sid: "NotTheUninstallersProgress", Effect: "Deny", NotAction: ["s3:PutObject"], Resource: o.statusBucket },
    { Sid: "WindowNoIamUsersOrKeys", Effect: "Deny", Action: ["iam:CreateUser", "iam:CreateAccessKey", "iam:CreateLoginProfile"], Resource: "*" },
  ];
}

/** The window policy for one mode (keep the data, or delete everything), still with tokens. */
export function uninstallWindowTemplate(n: UninstallNames, mode: "keep" | "everything"): PolicyDocument {
  return doc(uninstallWindowStatements(n).filter((x) => mode === "everything" || !x.Sid.startsWith(DATA_SID)));
}

/** The statements in parts that each fit a standard SSM parameter (4 KB). */
export function uninstallWindowParts(n: UninstallNames, max = 3200): string[] {
  const parts: Statement[][] = [[]];
  for (const st of uninstallWindowStatements(n)) {
    const cur = parts[parts.length - 1];
    if (cur.length && JSON.stringify([...cur, st]).length > max) parts.push([st]);
    else cur.push(st);
  }
  return parts.map((p) => JSON.stringify(p));
}

export interface WindowValues {
  userId: string;
  expires: string;
  ids: string[];
  launch: string[];
  setup: string[];
  siblings: string[];
  buckets?: string[];
  data?: string[];
}

/**
 * The window with the install's names filled in, exactly as the window
 * function does it (infra/cfn/uninstall/window.py, `expand`).
 */
export function expandWindow(statements: Statement[], v: WindowValues, mode: "keep" | "everything"): PolicyDocument {
  const subs: [string, string[]][] = [
    [TOKENS.userId, [v.userId]], [TOKENS.expires, [v.expires]], [TOKENS.id, v.ids], [TOKENS.launch, v.launch], [TOKENS.setup, v.setup], [TOKENS.sib, v.siblings], [TOKENS.bucket, v.buckets ?? []], [TOKENS.data, v.data ?? []],
  ];
  const many = (s: string): string[] => {
    for (const [t, vals] of subs) if (s.includes(t)) return vals.flatMap((x) => many(s.split(t).join(x)));
    return [s];
  };
  const ex = (x: unknown): unknown => {
    if (Array.isArray(x)) return x.flatMap((y) => (typeof y === "string" ? many(y) : [ex(y)]));
    if (typeof x === "string") {
      const m = many(x);
      return m.length === 1 && m[0] === x ? x : m;
    }
    if (x && typeof x === "object") return Object.fromEntries(Object.entries(x).map(([k, y]) => [k, ex(y)]));
    return x;
  };
  const empty = (x: unknown): boolean => (Array.isArray(x) ? x.length === 0 : !!x && typeof x === "object" && Object.values(x).some(empty));
  const out = statements
    .filter((x) => mode === "everything" || !x.Sid.startsWith(DATA_SID))
    .map((x) => ex(x) as Statement)
    .filter((x) => !empty(x.Resource ?? x.NotResource) && !empty(x.Condition ?? {}));
  return doc(out);
}
